const express = require('express');
const app = express();
const logger = (req, res, next) => { console.log(req.method, req.url); next(); };
const checkAuth = (req, res, next) => { if (req.headers.authorization) next(); else res.status(401).json({ error: 'no token' }); };
app.use(logger);
app.use(express.json());
app.use(checkAuth);
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);
  res.status(200).json({ id: id, lang: req.query.lang });
});
app.use((err, req, res, next) => { res.status(500).json({ error: 'server error' }); });
app.listen(3000);
